select extensions.ok((select count(*)=26 from public.admin_organization_people('f3200000-0000-4000-8000-000000000001','client','all',0)), 'RPC bounds each page to 25 plus one lookahead');
select extensions.ok((select count(*)=4 from public.admin_organization_people('f3200000-0000-4000-8000-000000000001','client','all',25)), 'Second page returns remaining membership episodes');
select extensions.ok((select count(*)=1 from (select id from public.admin_organization_people('f3200000-0000-4000-8000-000000000001','client','all',0) intersect select id from public.admin_organization_people('f3200000-0000-4000-8000-000000000001','client','all',25)) overlap), 'Pages overlap only at the intentional lookahead row');
select extensions.ok((select array_agg(id)=array_agg(id order by id) from public.admin_organization_people('f3200000-0000-4000-8000-000000000001','client','inactive',0)), 'Equal names and users retain deterministic episode ordering');
