select extensions.ok((select prosecdef and provolatile='s' and 'search_path=""'=any(proconfig) from pg_proc where oid='public.admin_organization_people(uuid,text,text,integer)'::regprocedure), 'Roster is a stable definer with a fixed empty search path');
select extensions.ok((select has_function_privilege('authenticated','public.admin_organization_people(uuid,text,text,integer)','EXECUTE') and not has_function_privilege('anon','public.admin_organization_people(uuid,text,text,integer)','EXECUTE') and not has_function_privilege('service_role','public.admin_organization_people(uuid,text,text,integer)','EXECUTE')), 'Only authenticated callers may attempt the guarded RPC');
select * from extensions.finish();
rollback;
